        # handle [] or [[]]
        if not m:
            return []
        # if m = [[]] or rows empty, return []
        try:
            if all(len(r)==0 for r in m):
                return []
        except:
            return []
    res=[]
    top, bottom = 0, len(m)-1
    left, right = 0, len(m[0])-1
    while top<=bottom and left<=right:
        for c in range(left, right+1):
            res.append(m[top][c])
        top+=1
        if top>bottom: break
        for r in range(top, bottom+1):
            res.append(m[r][right])
        right-=1
        if left>right: break
        for c in range(right, left-1, -1):
            res.append(m[bottom][c])
        bottom-=1
        if top>bottom: break
        for r in range(bottom, top-1, -1):
            res.append(m[r][left])
        left+=1
    return res

