def solve(m):
    if not m:
        return 1
    n = len(m)
    if n == 1:
        return m[0][0]
    # Bareiss algorithm for exact integer determinant
    M = [row[:] for row in m]
    sign = 1
    prev = 1
    for i in range(n):
        # Find pivot
        pivot = None
        for r in range(i, n):
            if M[r][i] != 0:
                pivot = r
                break
        if pivot is None:
            return 0
        if pivot != i:
            M[i], M[pivot] = M[pivot], M[i]
            sign = -sign
        for j in range(i+1, n):
            for k in range(i+1, n):
                M[j][k] = (M[i][i]*M[j][k] - M[j][i]*M[i][k]) // prev
            M[j][i] = 0
        prev = M[i][i]
    det = sign
    for i in range(n):
        det *= M[i][i]
    return det

