def solve(n, edges):
    try:
        n = int(n)
    except:
        return -1
    if n <= 0:
        return -1
    if n == 1:
        return 0
    if edges is None:
        return -1
    try:
        elist = list(edges)
    except:
        return -1
    adj = [[] for _ in range(n)]
    has_neg = False
    for e in elist:
        try:
            a, b, w = e
        except:
            continue
        try:
            a = int(a); b = int(b)
            w = float(w) if isinstance(w, float) else int(w) if isinstance(w, int) else float(w)
        except:
            continue
        if not (0 <= a < n and 0 <= b < n):
            continue
        if w < 0:
            has_neg = True
        adj[a].append((b, w))
        adj[b].append((a, w))
    import heapq
    INF = float('inf')
    if not has_neg:
        dist = [INF]*n
        dist[0] = 0
        pq = [(0, 0)]
        while pq:
            d, u = heapq.heappop(pq)
            if d != dist[u]:
                continue
            if u == n-1:
                break
            for v, w in adj[u]:
                nd = d + w
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))
        if dist[n-1] == INF:
            return -1
        r = dist[n-1]
        return int(r) if isinstance(r, float) and r.is_integer() else r
    else:
        # Bellman-Ford for negative weights (undirected -> directed pairs)
        dist = [INF]*n
        dist[0]=0
        dedges=[]
        for u in range(n):
            for v,w in adj[u]:
                dedges.append((u,v,w))
        for _ in range(n-1):
            upd=False
            for u,v,w in dedges:
                if dist[u]!=INF and dist[u]+w < dist[v]:
                    dist[v]=dist[u]+w
                    upd=True
            if not upd:
                break
        if dist[n-1]==INF:
            return -1
        r=dist[n-1]
        return int(r) if isinstance(r,float) and r.is_integer() else r

